insert into public.material_price_history (workspace_id, material_id, reference_month, cost)
select
  m.workspace_id,
  m.id,
  d.reference_month,
  round(m.cost * d.factor, 2)
from public.materials m
cross join (values
  (date '2026-04-01', 0.91),
  (date '2026-05-01', 0.93),
  (date '2026-06-01', 0.95),
  (date '2026-07-01', 0.94),
  (date '2026-08-01', 0.98),
  (date '2026-09-01', 1.00)
) as d(reference_month, factor)
where m.workspace_id = 'a0000000-0000-4000-8000-000000000001'
on conflict (material_id, reference_month) do update set cost = excluded.cost;

